// Original bounded phrase combinations; complete catalogs receive independent language review.
export const frenchChallenges=[{id:'find',title:'Find and follow'},{id:'clarify',title:'Ask a precise question'},{id:'message',title:'A recent action and a plan'}];
const names={salon:['le salon','the living room'],cuisine:['la cuisine','the kitchen'],chambre:['la chambre','the bedroom'],entree:["l’entrée",'the entrance hall']};
const fromRoom=r=>({salon:'du salon',cuisine:'de la cuisine',chambre:'de la chambre',entree:"de l’entrée"}[r]);
const roomPhrase=r=>`dans ${names[r][0]}`,roomMeaning=r=>`in ${names[r][1]}`;
const place=r=>['salon','cuisine'].includes(r)?['sur la table','on the table']:['sur l’étagère','on the shelf'];
const orders=[['salon','cuisine','chambre','entree'],['cuisine','chambre','entree','salon'],['chambre','entree','salon','cuisine'],['entree','salon','cuisine','chambre'],['cuisine','salon','entree','chambre'],['chambre','cuisine','salon','entree']];
const objects=[['sac','le sac','the bag','préparer une sortie','prepare for an outing'],['livre','le livre','the book','lire une histoire','read a story'],['tasse','la tasse','the cup','préparer le goûter','prepare the afternoon snack']];
function options(pairs,index,turn){const a=pairs.map((p,i)=>({text:p[0],meaning:p[1],match:i===index}));for(let i=0;i<turn%3;i++)a.push(a.shift());return a.map((p,i)=>({id:`choice-${i+1}`,text:p.text,meaning:p.meaning,outcome:p.match?'match':'different',feedback:p.match?'Ce choix correspond au message et au plan.':'Compare le message et le plan. Tu peux demander une précision ou de l’aide.'}));}
function question(id,prompt,meaning,pairs,index,n,guided,guidedMeaning,hint,hintMeaning,example,exampleMeaning){return {id,prompt,meaning,choices:options(pairs,index,n),guided,guidedMeaning,hint,hintMeaning,example,exampleMeaning};}
function map(order,obj,target){return order.map(r=>({id:r,name:names[r][0],objects:[['salon','cuisine'].includes(r)?[`table-${r}`,'la table']:[`etagere-${r}`,"l’étagère"],...(r===target?[[obj[0],`${obj[1]} · ${place(r)[0]}`]]:[])]}));}
export function frenchMission(kind,serial){
 if(!frenchChallenges.some(c=>c.id===kind)||!Number.isSafeInteger(serial)||serial<1||serial>999999)return null;
 const n=(serial-1)%6,order=orders[n],obj=objects[n%3],target=order[(n+1)%4],later=order[(n+2)%4],rooms=map(order,obj,target),loc=`${place(target)[0]}, ${roomPhrase(target)}`,engLoc=`${place(target)[1]}, ${roomMeaning(target)}`;
 const base={id:`mission-${kind}-${serial}`,title:`Une mission · ${frenchChallenges.find(c=>c.id===kind).title} · ${serial}`,adaptive:{version:1,kind,serial,caseId:`${kind}-${n+1}`,concept:kind},rooms};
 const locationPairs=[target,...order.filter(r=>r!==target).slice(0,2)].map(r=>[`${place(r)[0]}, ${roomPhrase(r)}`,`${place(r)[1]}, ${roomMeaning(r)}`]);
 const support=['Lis le message, puis cherche la pièce et la position de l’objet.','Read the message, then look for the room and the object’s position.','« Sur » indique une position. « Dans » indique ici la pièce.','“On” describes a position. “In” identifies the room here.','Sur un autre plan, la clé est dans la cuisine. Cherche dans cette pièce.','On another plan, the key is in the kitchen. Look in that room.'];
 if(kind==='find'){
  // All routes follow two adjacent positions on the page: top-left → top-right → bottom-right.
  const start=order[0],finish=order[3];
  return {...base,intro:`Pour ${obj[3]}, va chercher ${obj[1]}. ${obj[1][0].toUpperCase()+obj[1].slice(1)} est ${loc}.`,meaning:`To ${obj[4]}, go and get ${obj[2]}. ${obj[2][0].toUpperCase()+obj[2].slice(1)} is ${engLoc}.`,teach:'Le plan se lit sur la page : à gauche, à droite, au-dessus et en dessous. Les directions ne changent pas avec la personne qui marche. Cherche une pièce, puis une position précise.',teachMeaning:'Read the plan on the page: to the left, to the right, above and below. The directions do not change with the person walking. Look for a room, then a precise position.',items:[
   question('find',`Où vas-tu chercher ${obj[1]} ?`,`Where are you going to get ${obj[2]}?`,locationPairs,0,n,...support),
   question('route',`Pars ${fromRoom(start)}. Sur le plan, va dans la pièce juste à droite, puis dans la pièce juste en dessous. Où arrives-tu ?`,`Start from ${names[start][1]}. On the plan, go into the room immediately to the right, then into the room immediately below. Where do you arrive?`,[finish,order[1],order[2]].map(r=>names[r]),0,n+1,`Sur ce plan, pars ${fromRoom(order[2])}. La pièce juste au-dessus est ${names[order[0]][0]}.`,`On this plan, start from ${names[order[2]][1]}. The room immediately above is ${names[order[0]][1]}.`,'Suis les deux étapes dans l’ordre sur la page.','Follow both steps in order on the page.','Sur un autre plan, la cuisine est à gauche du salon. On va du salon vers la gauche pour arriver dans la cuisine.','On another plan, the kitchen is to the left of the living room. Go left from the living room to arrive in the kitchen.')
  ]};
 }
 if(kind==='clarify'){
  const shelf=n%2===1,pair=shelf?['chambre','entree']:['salon','cuisine'],where=pair[Math.floor(n/2)%2],noun=shelf?"l’étagère":'la table',label=shelf?'étagère':'table',enNoun=shelf?'shelf':'table';
  const updatedRooms=map(order,obj,where);
  // In a clarification case the object is to be placed after the reply, so initially absent.
  const initialRooms=rooms.map(r=>({...r,objects:r.objects.filter(p=>p[0]!==obj[0])}));
  const reply=`Sur ${noun}, ${roomPhrase(where)}.`,replyMeaning=`On the ${enNoun}, ${roomMeaning(where)}.`;
  return {...base,rooms:initialRooms,updatedRooms,intro:`Un message dit : « Pose ${obj[1]} sur ${noun}. » Il y a deux ${label}s : une ${roomPhrase(pair[0])} et une ${roomPhrase(pair[1])}.`,meaning:`A message says: “Put ${obj[2]} on the ${enNoun}.” There are two ${shelf?'shelves':'tables'}: one ${roomMeaning(pair[0])} and one ${roomMeaning(pair[1])}.`,teach:'Le message ne précise pas la pièce. Demander une précision permet de choisir sans inventer une information.',teachMeaning:'The message does not specify the room. Asking for clarification lets you choose without inventing information.',items:[
   question('question','Quelle question permet de choisir le bon endroit ?','Which question lets you choose the right place?',[[`Quelle ${label} : celle ${fromRoom(pair[0])} ou celle ${fromRoom(pair[1])} ?`,`Which ${enNoun}: the one in ${names[pair[0]][1]} or the one in ${names[pair[1]][1]}?`],[`De quelle couleur est ${obj[1]} ?`,`What color is ${obj[2]}?`],[`À quelle heure faut-il poser ${obj[1]} ?`,`At what time should you put down ${obj[2]}?`]],0,n,'Un message dit « près de la porte ». Tu demandes : « Dans quelle pièce ? »','A message says “near the door.” You ask: “In which room?”','Il manque le nom de la pièce, pas la couleur ni l’heure.','The room name is missing, not the color or the time.','« Dans quelle pièce se trouve la chaise ? » demande une position plus précise.','“In which room is the chair?” asks for a more precise location.'),
   question('location',`Après la précision, où faut-il poser ${obj[1]} ?`,`After the clarification, where should you put ${obj[2]}?`,[where,pair.find(r=>r!==where),order.find(r=>!pair.includes(r))].map(r=>[`${place(r)[0]}, ${roomPhrase(r)}`,`${place(r)[1]}, ${roomMeaning(r)}`]),0,n+1,'Lis la réponse avant de choisir la pièce.','Read the reply before choosing the room.','La réponse donne la pièce qui manquait.','The reply gives the room that was missing.','Si une réponse précise « dans le salon », choisis le salon.','If a reply specifies “in the living room,” choose the living room.')
  ],newMessage:reply,newMeaning:replyMeaning,writing:'Écris une question pour demander une précision. Une personne lira tes mots : il n’y a pas de note automatique.',writingMeaning:'Write a question to ask for clarification. A person will read your words: there is no automatic grade.',revisionPrompt:'Revise your message after the reply. Give the precise location.'};
 }
 return {...base,updatedRooms:map(order,obj,later),intro:`Je viens de lire le message. Je vais chercher ${obj[1]} ${roomPhrase(target)} pour ${obj[3]}. ${obj[1][0].toUpperCase()+obj[1].slice(1)} est ${loc}.`,meaning:`I have just read the message. I am going to get ${obj[2]} from ${names[target][1]} to ${obj[4]}. ${obj[2][0].toUpperCase()+obj[2].slice(1)} is ${engLoc}.`,teach:'« Je viens de lire » indique une action très récente. « Je vais chercher » indique une action à venir. On emploie un infinitif après « je viens de » ou « je vais ». Devant une voyelle, « de » devient « d’ » : « Je viens d’arriver. »',teachMeaning:'“I have just read” describes a very recent action. “I am going to get” describes a coming action. Use an infinitive after “je viens de” or “je vais.” Before a vowel, “de” becomes “d’”: “I have just arrived.”',items:[
  question('plan','Quelle action est prévue ?','Which action is planned?',[[`chercher ${obj[1]}`,`get ${obj[2]}`],['lire le message','read the message'],[`poser ${obj[1]}`,`put down ${obj[2]}`]],0,n,'Je viens de répondre. Je vais partir. Partir est l’action à venir.','I have just replied. I am going to leave. Leaving is the coming action.','Repère « je vais » dans le message.','Find “je vais” in the message.','Je viens d’arriver. Je vais lire. Lire est l’action prévue.','I have just arrived. I am going to read. Reading is the planned action.'),
  question('location',`D’après le nouveau message, où vas-tu chercher ${obj[1]} ?`,`According to the new message, where are you going to get ${obj[2]}?`,[later,target,order.find(r=>r!==later&&r!==target)].map(r=>[`${place(r)[0]}, ${roomPhrase(r)}`,`${place(r)[1]}, ${roomMeaning(r)}`]),0,n+1,'Un nouveau message peut changer la place d’un objet. Lis-le avant de partir.','A new message can change an object’s location. Read it before leaving.','Utilise la nouvelle pièce, pas l’ancienne.','Use the new room, not the old one.','Sur un autre plan, la clé était dans la cuisine. Un message indique maintenant le salon : cherche dans le salon.','On another plan, the key was in the kitchen. A message now specifies the living room: look in the living room.')
 ],newMessage:`${obj[1][0].toUpperCase()+obj[1].slice(1)} n’est plus ${roomPhrase(target)}. Je viens de déplacer ${obj[1]}. Maintenant, ${obj[1]} est ${place(later)[0]}, ${roomPhrase(later)}.`,newMeaning:`${obj[2][0].toUpperCase()+obj[2].slice(1)} is no longer ${roomMeaning(target)}. I have just moved it. Now ${obj[2]} is ${place(later)[1]}, ${roomMeaning(later)}.`,writing:'Écris un court message avec une action récente et un projet. Une personne lira tes mots : il n’y a pas de note automatique.',writingMeaning:'Write a short message with a recent action and a plan. A person will read your words: there is no automatic grade.',revisionPrompt:'Revise your French message after the reply changes the location.'};
}
